-- submissions/schedule-contact-purge
-- A reporter's contact is deleted 30 days after the decision (SPEC 12.3).
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

update "submissions"
set "contact_purge_after" = now() + interval '30 days'
where ("submissions"."id" = $1
  and "submissions"."contact_encrypted" is not null);
